#include "mka/playback_owner.hpp"
#include "mka/runtime_preparation.hpp"
#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <stdexcept>
using namespace mka::sound;
namespace {thread_local bool throw_protocol_unload_once=false;}
extern "C" bool real_protocol_unload(AudioBankProtocol*,const AudioBankCommand&,AudioProtocolFailure&) __asm__("__real__ZN3mka5sound17AudioBankProtocol6unloadERKNS0_16AudioBankCommandERNS0_20AudioProtocolFailureE");
extern "C" bool wrapped_protocol_unload(AudioBankProtocol*,const AudioBankCommand&,AudioProtocolFailure&) __asm__("__wrap__ZN3mka5sound17AudioBankProtocol6unloadERKNS0_16AudioBankCommandERNS0_20AudioProtocolFailureE");
extern "C" bool wrapped_protocol_unload(AudioBankProtocol* self,const AudioBankCommand& c,AudioProtocolFailure& f){if(throw_protocol_unload_once){throw_protocol_unload_once=false;throw std::runtime_error("fixture lower Protocol unload uncertainty");}return real_protocol_unload(self,c,f);}
namespace {
void check(bool ok,const char* why){if(!ok){std::fprintf(stderr,"FAIL: %s\n",why);std::abort();}}
constexpr std::uint32_t token=0xd81f7321;
AudioBankCommand command(AudioBankOpcode op){AudioBankCommand c;c.opcode=op;c.bank_token={token};return c;}
NativePlayParameters parameters(std::uint16_t flags=0){return {initial_program_control_factors(),initial_program_control_factors(),{{1,14336,false},{1,-16384,true},{1,14336,false},{1,-16384,false},2048},{1000},3,flags};}
AudioBankService service(const char* path){AudioBanksFailure bf;auto session=AudioBankSession::open(path,std::nullopt,bf);check(bool(session),"actual session");AudioProtocolFailure pf;auto protocol=AudioBankProtocol::create(std::move(*session),pf);check(bool(protocol),"actual protocol");BankServiceFailure f;auto result=AudioBankService::create(std::move(*protocol),f);check(bool(result),"actual Service");AudioBankCommand load;load.opcode=AudioBankOpcode::load_sync;load.pathname="announcr";auto bank=result->load_sync(load,{token},f);check(bank&&bank->bank.value==token,"actual full-token ANNOUNCR load");return std::move(*result);}
NativePlaybackOwner owner(AudioBankService&& service){PlaybackFailure f;auto result=NativePlaybackOwner::create(std::move(service),48000,f);check(bool(result),"actual default owner");return std::move(*result);}
void reject_flags(const char* path){
 auto o=owner(service(path));PlaybackFailure f;auto context=o.create_sound_context(f);check(bool(context),"explicit context");
 for(auto flags:{std::uint16_t(1),std::uint16_t(8)}){check(!o.play(*context,command(AudioBankOpcode::play),parameters(flags),f)&&f.kind==PlaybackError::unsupported_play_flags,"unsupported actual combined play flags reject before handle publication");auto observed=o.observe_sound_context(*context,f);check(observed&&observed->pending_preparations==0&&observed->programs==0&&observed->active_voices==0,"rejected flags leave no pending handle or context resources");}
 check(o.unload(command(AudioBankOpcode::unload),f)&&o.release_sound_context(*context,f)&&o.close_when_idle(f),"unsupported flag rollback releases actual Service keepers");
}
void default_copy(const char* path){
 auto o=owner(service(path));PlaybackFailure f;auto context=o.create_sound_context(f);check(bool(context),"explicit normal context");auto handle=o.play(*context,command(AudioBankOpcode::play),parameters(0x80),f);check(bool(handle),"actual default path constructs private copy");auto observed=o.observe(*handle,f);check(observed&&observed->private_copy_bound&&!observed->resources_retired&&observed->effective_play_flags==0x82,"actual source program flags2 OR explicit caller80 visible");
 auto start=o.tick(*handle,{1000},f);check(start&&start->kind==ProgramStepKind::sample_start&&start->owner&&start->owner->normal_instances.size()==1,"actual default copy drives Executor start");const auto& instance=start->owner->normal_instances[0];check(!instance.cache_reference&&instance.native_template.gain_q14==16384&&instance.native_template.pan_q14==0&&instance.native_template.pitch_q12==4096&&start->start.parameter_44==16383,"private copy retains real donor metadata and separately applied command controls");auto pcm=o.mix(512,f);check(pcm&&std::any_of(pcm->begin(),pcm->end(),[](float x){return x!=0;}),"default private-copy actual native PCM");
 check(o.stop(*handle,f)&&bool(o.mix(32,f)),"ordinary mode0 output cleanup");observed=o.observe(*handle,f);check(observed&&observed->active_voices==0&&observed->private_copy_bound&&!observed->resources_retired,"inactive mode0 still owns private copy and semantic keeper");check(!o.unload(command(AudioBankOpcode::play),f)&&f.service.kind==BankServiceError::wrong_command,"wrong-opcode unload rejected before copy detachment");observed=o.observe(*handle,f);check(observed&&observed->private_copy_bound&&!observed->resources_retired,"wrong-opcode unload preserves actual private copy");check(o.stop(*handle,f)&&o.stop(*handle,f),"ordinary stopped owner cleanup idempotent");auto exported=start->owner;auto sample=start->clip;check(o.unload(command(AudioBankOpcode::unload),f),"idle unload retires actual copy before Service unload");check(!o.observe(*handle,f)&&f.kind==PlaybackError::retired_handle,"successful unload retires public handle");check(!exported->normal_instances[0].cache_reference&&!sample->pcm[0].samples.empty(),"exported clone data and PCM survive unload without semantic reference");check(o.release_sound_context(*context,f)&&o.close_when_idle(f),"context release and idle close after resource teardown");
}
void refusal_retry(const char* path){
 auto s=service(path);PreparationFailure pf;BankServiceFailure sf;auto external=s.acquire_runtime_program(command(AudioBankOpcode::play),pf,sf);check(bool(external),"actual external semantic keeper before owner move");auto o=owner(std::move(s));PlaybackFailure f;auto context=o.create_sound_context(f);check(bool(context),"refusal context");auto handle=o.play(*context,command(AudioBankOpcode::play),parameters(),f);check(bool(handle)&&o.stop(*handle,f),"actual idle stopped private copy");
 check(!o.unload(command(AudioBankOpcode::unload),f)&&f.kind==PlaybackError::service_failed&&f.service.kind==BankServiceError::runtime_reference_active,"known Service refusal due independently owned runtime reference");auto observed=o.observe(*handle,f);check(observed&&observed->resources_retired&&!observed->private_copy_bound&&observed->explicitly_stopped,"known refusal preserves idle handle observation with retired copy resources");auto idle_tick=o.tick(*handle,{9000},f);check(idle_tick&&idle_tick->kind==ProgramStepKind::finished,"tick after known unload refusal uses retained idle executor safely");auto silent=o.mix(16,f);check(silent&&std::all_of(silent->begin(),silent->end(),[](float v){return v==0;}),"mix after retired copy sees no outputs");check(o.stop(*handle,f),"stop after retired copy is idempotent");check(external->release(pf),"release actual blocking external semantic reference");check(o.unload(command(AudioBankOpcode::unload),f),"same actual bank unload retries after known refusal");check(!o.observe(*handle,f)&&f.kind==PlaybackError::retired_handle,"successful retry retires exact idle handle");check(o.release_sound_context(*context,f)&&o.close_when_idle(f),"known refusal path context and Service teardown");
}
void release_and_close(const char* path){
 auto o=owner(service(path));PlaybackFailure f;auto context=o.create_sound_context(f);check(bool(context),"release context");auto handle=o.play(*context,command(AudioBankOpcode::play),parameters(),f);check(handle&&o.stop(*handle,f),"live idle stopped copy before close");check(o.observe(*handle,f)->private_copy_bound,"close must dispose a real retained copy");check(o.close_when_idle(f),"idle close itself retires copy and Service keeper");check(!o.tick(*handle,{1000},f)&&f.kind==PlaybackError::closed&&!o.release(*handle,f)&&f.kind==PlaybackError::closed,"closed owner rejects stale public operations by name");
}
void context_cleanup(const char* path){
 auto o=owner(service(path));PlaybackFailure f;auto context=o.create_sound_context(f);check(bool(context),"cleanup context");auto handle=o.play(*context,command(AudioBankOpcode::play),parameters(),f);check(handle&&o.stop(*handle,f)&&o.observe(*handle,f)->private_copy_bound,"context cleanup starts with actual live idle copy");check(o.release_sound_context(*context,f),"context release disposes its idle copies and keepers");check(!o.observe(*handle,f)&&f.kind==PlaybackError::retired_handle,"context cleanup retires exact play handle");check(o.unload(command(AudioBankOpcode::unload),f)&&o.close_when_idle(f),"context disposal releases actual Service runtime reservation");
}
void lower_unload_uncertainty(const char* path){
 auto o=owner(service(path));PlaybackFailure f;auto context=o.create_sound_context(f);check(bool(context),"uncertain unload context");auto handle=o.play(*context,command(AudioBankOpcode::play),parameters(),f);check(handle&&o.stop(*handle,f),"uncertain unload starts with actual idle copy");
 AudioBankCommand load;load.opcode=AudioBankOpcode::load_sync;load.pathname="announcr";constexpr std::uint32_t other=0x92f17321;auto loaded=o.load_sync(load,{other},f);check(loaded&&loaded->bank.value==other,"unrelated actual bank loaded before lower failure");
 throw_protocol_unload_once=true;check(!o.unload(command(AudioBankOpcode::unload),f)&&f.kind==PlaybackError::service_failed&&f.service.kind==BankServiceError::native_exception&&!throw_protocol_unload_once,"actual Service catches lower Protocol exception");
 check(!o.play(*context,command(AudioBankOpcode::play),parameters(),f)&&f.kind==PlaybackError::bank_state_unknown,"uncertain lower bank cannot reopen Owner play admission");check(!o.unload(command(AudioBankOpcode::unload),f)&&f.kind==PlaybackError::bank_state_unknown,"uncertain lower bank cannot implicitly retry unload");
 auto other_command=command(AudioBankOpcode::play);other_command.bank_token={other};auto other_handle=o.play(*context,other_command,parameters(),f);check(other_handle&&o.tick(*other_handle,{1000},f),"unrelated bank still admits actual output");auto mixed=o.mix(128,f);check(mixed&&std::any_of(mixed->begin(),mixed->end(),[](float v){return v!=0;}),"unrelated actual output remains usable after bank quarantine");check(o.stop(*other_handle,f)&&bool(o.mix(32,f))&&o.release(*other_handle,f),"unrelated output cleanup remains usable");
}
void close_refusal(const char* path){
 auto s=service(path);PreparationFailure pf;BankServiceFailure sf;auto external=s.acquire_runtime_program(command(AudioBankOpcode::play),pf,sf);check(bool(external),"close-refusal independent keeper");auto o=owner(std::move(s));PlaybackFailure f;auto context=o.create_sound_context(f);check(bool(context),"close-refusal context");auto handle=o.play(*context,command(AudioBankOpcode::play),parameters(),f);check(handle&&o.stop(*handle,f),"close-refusal idle copy");
 check(!o.close_when_idle(f)&&f.kind==PlaybackError::service_failed&&f.service.kind==BankServiceError::runtime_reference_active,"actual known close refusal after own copy cleanup");auto observed=o.observe(*handle,f);check(observed&&observed->resources_retired&&!observed->private_copy_bound,"known close refusal retains safe idle handle metadata");auto tick=o.tick(*handle,{9999},f);check(tick&&tick->kind==ProgramStepKind::finished&&bool(o.mix(16,f))&&o.stop(*handle,f),"tick mix and stop after close refusal do not dereference disposed copy");check(o.release(*handle,f)&&!o.observe(*handle,f)&&f.kind==PlaybackError::retired_handle,"release safely removes already resource-retired handle");check(o.release_sound_context(*context,f)&&external->release(pf)&&o.close_when_idle(f),"close refusal admits cleanup and exact retry after external keeper release");
}
}
int main(int argc,char** argv){if(argc!=2){std::fprintf(stderr,"usage: test_default_playback_runtime <pinned_original_MS2>\n");return 2;}reject_flags(argv[1]);default_copy(argv[1]);refusal_retry(argv[1]);release_and_close(argv[1]);context_cleanup(argv[1]);close_refusal(argv[1]);lower_unload_uncertainty(argv[1]);std::puts("PASS_NATIVE_DEFAULT_PLAYBACK_RUNTIME: 7 actual default runtime/copy/flag/retirement cases; no source activation/callback/device/fidelity claim");return std::fflush(stdout)||std::ferror(stdout)?1:0;}
